func (h *MessageHandler) handleToolsComplete(
	ctx context.Context,
	loopID string,
	entity agentic.LoopEntity,
	cm *ContextManager,
	result *HandlerResult,
) (HandlerResult, error) {
	// Check for cancellation before proceeding
	if err := ctx.Err(); err != nil {
		return *result, err
	}

	// Increment iteration counter
	err := h.loopManager.IncrementIteration(loopID)
	if err != nil {
		// LoopManager.IncrementIteration can fail for two structurally
		// different reasons: budget exhaustion (agentic.ErrMaxIterationsReached,
		// returned by LoopEntity.IncrementIteration) or an unrelated
		// operational failure such as "loop not found". Only the sentinel
		// means exhaustion — anything else must propagate as an ordinary
		// handler error instead of being misreported as max_iterations
		// (pre-merge review M1).
		if !errors.Is(err, agentic.ErrMaxIterationsReached) {
			return *result, errs.Wrap(err, "agentic-loop", "handleToolsComplete", "increment iteration")
		}

		// Max iterations reached - mark as failed.
		// Drain any pending tools first so KV-persisted context for this
		// loop carries clean tool-pair structure (mode d of orphan
		// recovery — iteration limit hit while tools still in-flight).
		h.drainPendingToolFailures(loopID, "max iterations reached before tool results returned")

		if transitionErr := h.loopManager.TransitionLoop(loopID, agentic.LoopStateFailed); transitionErr != nil {
			return *result, errs.Wrap(transitionErr, "agentic-loop", "handleToolsComplete", fmt.Sprintf("transition loop to failed state (original error: %v)", err))
		}
		result.State = agentic.LoopStateFailed
		result.MaxIterationsReached = true

		// Update entity with completion data for KV persistence (enables SSE delivery)
		errorMsg := fmt.Sprintf("max iterations (%d) reached", entity.MaxIterations)
		if updateErr := h.loopManager.UpdateCompletion(loopID, agentic.OutcomeFailed, "", errorMsg); updateErr != nil {
			h.logger.Warn("failed to update completion for max iterations",
				slog.String("loop_id", loopID),
				slog.String("error", updateErr.Error()))
		}

		// Publish failure events for reactive workflows to observe
		if failure, failMsgs, fErr := h.BuildFailureMessages(loopID, "max_iterations", errorMsg); fErr == nil {
			result.PublishedMessages = failMsgs
			result.FailureState = failure
		}

		return *result, nil
	}

	// Get the new iteration count for GC
	newIteration := h.loopManager.GetCurrentIteration(loopID)

	h.absorbToolResultsIntoContext(loopID, cm)

	if err := h.publishIterationRequest(ctx, loopID, entity, cm, result, newIteration); err != nil {
		return *result, err
	}

	return *result, nil
}

func (m *LoopManager) SettleRequest(loopID, requestID string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.settleOutstandingLocked(loopID, requestID)
	if entity, exists := m.loops[loopID]; exists && requestID != "" && entity.PendingContinuationRequestID == requestID {
		entity.PendingContinuation = false
		entity.PendingContinuationRequestID = ""
		entity.PendingContinuationPrompt = ""
	}
}

func (m *LoopManager) GetLoop(loopID string) (agentic.LoopEntity, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	if loopID == "" {
		return agentic.LoopEntity{}, errs.WrapInvalid(fmt.Errorf("loop ID cannot be empty"), "LoopManager", "GetLoop", "validate loop ID")
	}

	entity, exists := m.loops[loopID]
	if !exists {
		// ErrLoopNotFound, as CancelLoop and ResolveApprovalIfPending wrap it:
		// the carrier reads "no longer held" by the sentinel (#1377 W3/W4), so
		// a released loop is told apart from an invalid ID, which stays
		// Invalid above and is never acknowledged as stale.
		return agentic.LoopEntity{}, errs.Wrap(fmt.Errorf("loop %s: %w", loopID, ErrLoopNotFound), "LoopManager", "GetLoop", "find loop")
	}

	// A struct copy is shallow, so the applied set would travel out of this
	// lock as the SAME map the live entity holds — and every caller reads the
	// returned entity after this lock is released. The record writers
	// (writeLoopRecord, marshalLoopRecord) marshal it into the record's bytes
	// while StoreToolResult, on the handler
	// goroutine, writes the same map under this mutex: a data race, not a
	// stale read. One copy makes the returned entity a value the caller owns.
	//
	// The applied set is the only reference field a live loop mutates in
	// place. PendingApproval is replaced wholesale by BeginAwaitingApproval
	// and cleared by ResolveApproval, and Metadata is written once at birth.
	copied := *entity
	if entity.PendingToolResults != nil {
		copied.PendingToolResults = make(map[string]agentic.ToolResult, len(entity.PendingToolResults))
		maps.Copy(copied.PendingToolResults, entity.PendingToolResults)
	}
	return copied, nil
}

