func (h *MessageHandler) recoverEmptyContext(loopID string, cm *ContextManager, iteration, evicted int) []agentic.ChatMessage {
	prompt := h.loopManager.GetTaskPrompt(loopID)
	if prompt == "" {
		prompt = "Continue with the task."
	}

	h.logger.Warn("context empty after GC/repair — recovering with task prompt",
		slog.String("loop_id", loopID),
		slog.Int("iteration", iteration),
		slog.Int("evicted", evicted))

	synthetic := agentic.ChatMessage{
		Role:    "user",
		Content: fmt.Sprintf("[Context recovered after tool pair cleanup]\n\nOriginal task: %s\n\nPrevious tool calls encountered errors. Please continue or try a different approach.", prompt),
	}
	_ = cm.AddMessage(RegionRecentHistory, synthetic)
	// The prompt is the BIRTH prompt (#1365, OQ5 (a′)), so a deferred turn
	// would be in no request once its context is gone: the request built here
	// is named its carrier and its answer settles the loop. The turn is
	// re-injected after the birth prompt, from the one place it is stored —
	// the entity's PendingContinuationPrompt — whether or not an earlier
	// request carried it: a carrier's truncation retry keeps the deferral
	// (F3), and an emptied context holds no user message, so this cannot
	// inject the turn a second time.
	if pending := h.loopManager.deferredContinuationPrompt(loopID); pending != "" {
		_ = cm.AddMessage(RegionRecentHistory, agentic.ChatMessage{Role: "user", Content: pending})
	}
	return cm.GetContext()
}

func BuildIterationBudgetMessage(iteration, maxIterations int) agentic.ChatMessage {
	pct := (iteration * 100) / maxIterations
	var content string
	switch {
	case pct > 75:
		content = fmt.Sprintf(iterationBudgetPrefix+" Iteration %d of %d (%d%% used). Budget nearly exhausted — finalize and submit your work now.", iteration, maxIterations, pct)
	case pct > 50:
		content = fmt.Sprintf(iterationBudgetPrefix+" Iteration %d of %d (%d%% used). Consider wrapping up — focus on completing the current objective.", iteration, maxIterations, pct)
	default:
		content = fmt.Sprintf(iterationBudgetPrefix+" Iteration %d of %d (%d%% used).", iteration, maxIterations, pct)
	}
	return agentic.ChatMessage{Role: "system", Content: content}
}

func (m *LoopManager) GetRole(loopID string) string {
	m.mu.RLock()
