func (h *MessageHandler) BuildFailureMessages(loopID, reason, errorMsg string) (*agentic.LoopFailedEvent, []PublishedMessage, error) {
	failure, err := h.buildFailureEvent(loopID, reason, errorMsg)
	if err != nil {
		return nil, nil, err
	}

	failureMsg := message.NewBaseMessage(failure.Schema(), failure, "agentic-loop")
	data, err := json.Marshal(failureMsg)
	if err != nil {
		return nil, nil, err
	}
	failureSubject, err := component.ResolveSubject(h.config.Ports.Outputs, "agent.failed", loopID)
	if err != nil {
		return nil, nil, err
	}

	return failure, []PublishedMessage{{
		Subject: failureSubject,
		Data:    data,
	}}, nil
}

func (m *LoopManager) UpdateCompletion(loopID, outcome, result, errMsg string) error {
	if !isValidOutcome(outcome) {
		return errs.WrapInvalid(fmt.Errorf("invalid outcome: %s", outcome), "LoopManager", "UpdateCompletion", "validate outcome")
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	entity, exists := m.loops[loopID]
	if !exists {
		return errs.Wrap(fmt.Errorf("loop %s not found", loopID), "LoopManager", "operation", "find loop")
	}

	entity.Outcome = outcome
	entity.Result = result
	entity.Error = errMsg
	entity.CompletedAt = time.Now()
	return nil
}

func (h *MessageHandler) handleLengthTruncation(ctx context.Context, loopID string, entity agentic.LoopEntity, cm *ContextManager, response agentic.AgentResponse, result *HandlerResult) error {
	preUtilization := cm.Utilization()
	completionTokens := response.TokenUsage.CompletionTokens
	modelLimit := cm.ModelLimit()

	// Branch 1: structurally can't recover. Either we already tried
	// (the prior retry hit the same wall) or there's nothing for the
	// compactor to compact away.
	//
	// The budget is read out of the loop's durable record rather than a
	// process-local counter (#1330): PublishedRequestID names this iteration's
	// retry ordinal, so ordinal 0 means the self-heal has not been spent and
	// ordinal 1 means it has. A replacement process reads the same answer its
	// predecessor would have, where the counter read zero and spent the budget
	// a second time under a name the first attempt had already published.
	retryCount := h.loopManager.publishedRetryOrdinal(loopID) + 1
	canRetry := preUtilization >= h.config.Context.CompactThreshold && retryCount == 1

	if !canRetry {
		compactionAttempted := retryCount > 1 // we got here through a retry that also truncated
		message := h.buildTruncationDiagnostic(modelLimit, completionTokens, preUtilization, 0, compactionAttempted)

		h.logger.Warn("model response truncated, failing loop",
			slog.String("loop_id", loopID),
			slog.String("finish_reason", response.FinishReason),
			slog.Int("completion_tokens", completionTokens),
			slog.Float64("pre_compact_utilization", preUtilization),
			slog.Int("model_limit", modelLimit),
			slog.Bool("compaction_attempted", compactionAttempted),
			slog.Int("retry_count", retryCount))

		return h.failLoop(result, loopID, agentic.OutcomeTruncated, "length_truncated", message)
	}

	// Branch 2: high utilization, first retry. Compact and re-request.
	h.logger.Info("length-truncated response triggered compaction retry",
		slog.String("loop_id", loopID),
		slog.Float64("pre_compact_utilization", preUtilization),
		slog.Int("completion_tokens", completionTokens),
		slog.Int("model_limit", modelLimit))

	beforeCompaction := cm.GetContext()
	compactStart := time.Now()
	compactResult, compactErr := h.compactor.Compact(ctx, cm)
	if compactErr != nil {
		// Compaction failed — fall through to the failure branch with a
		// diagnostic that names the failure. Nothing was published, so the
		// record still names the same request and the budget is untouched;
		// the parent decides whether a fresh-loop retry helps.
		message := fmt.Sprintf("truncated and compaction failed (model_limit=%d, utilization=%.0f%%, completion_tokens=%d, compactor_error=%s) — try a larger model or tune CompactThreshold/HeadroomTokens",
			modelLimit, preUtilization*100, completionTokens, compactErr.Error())
		return h.failLoop(result, loopID, agentic.OutcomeTruncated, "length_truncated", message)
	}
	compactDuration := time.Since(compactStart).Milliseconds()
	postUtilization := cm.Utilization()
	tokensSaved := compactResult.EvictedTokens - compactResult.NewTokens

	// Trajectory + ContextEvent for observability. Step type is
	// distinct from the routine-pre-iteration "context_compaction" so
	// operators reading a trajectory can tell retry-driven compaction
	// from threshold-driven compaction at a glance.
	result.ContextEvents = append(result.ContextEvents, agentic.ContextEvent{
		Type:        agentic.ContextEventCompactionRetry,
		LoopID:      loopID,
		UserID:      h.lookupLoopUserID(loopID),
		Iteration:   entity.Iterations,
		Utilization: preUtilization,
		TokensSaved: tokensSaved,
		Summary:     compactResult.Summary,
	})
	retryStep := agentic.TrajectoryStep{
		Timestamp:   time.Now(),
		StepType:    "context_compaction_retry",
		Response:    compactResult.Summary,
		TokensIn:    compactResult.EvictedTokens,
		TokensOut:   compactResult.NewTokens,
		Model:       compactResult.Model,
		Utilization: preUtilization,
		Duration:    compactDuration,
	}
	result.TrajectorySteps = append(result.TrajectorySteps, retryStep)
	appendTrajectoryObservation(result, trajectoryObservation{
		LoopID:            loopID,
		Kind:              agentic.TrajectoryKindContextCompacted,
		SourceKind:        agentic.TrajectorySourceCompaction,
		SourceCorrelation: "length_truncation_retry",
		CausalIteration:   positiveUint32(entity.Iterations),
		CausalPhase:       agentic.TrajectoryPhaseCompaction,
		ElapsedMS:         compactDuration,
		Status:            agentic.TrajectoryStatusCompleted,
		TokensIn:          positiveUint64(compactResult.EvictedTokens),
		TokensOut:         positiveUint64(compactResult.NewTokens),
		ModelPreview:      compactResult.Model,
		Evidence: trajectoryCompactionEvidence{
			Before: beforeCompaction,
			After:  cm.GetContext(),
			Result: compactResult,
		},
	})
	if _, addErr := h.trajectoryManager.addStep(loopID, retryStep); addErr != nil {
		h.logger.Warn("failed to add compaction-retry trajectory step",
			slog.String("loop_id", loopID),
			slog.String("error", addErr.Error()))
	}

	// Build and emit the retry agent.request from the freshly-compacted
	// context. We do NOT increment the iteration counter — this is a
	// within-iteration self-heal. The retry request's own name carries the
	// budget: it mints :N:1 at the same iteration, so a second truncation of
	// iteration N reads retry ordinal 1 and falls through to the hard fail.
	return h.emitRetryRequest(ctx, loopID, entity, cm, result, postUtilization)
}

func (m *LoopManager) AddPendingTool(loopID, callID string) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	if _, exists := m.loops[loopID]; !exists {
		return errs.Wrap(fmt.Errorf("loop %s not found", loopID), "LoopManager", "operation", "find loop")
	}

	if m.pendingTools[loopID] == nil {
		m.pendingTools[loopID] = make(map[string]bool)
	}

	m.pendingTools[loopID][callID] = true
	return nil
}

func (h *MessageHandler) resolveRunEntityID(runID string) string {
	if runID == "" {
		return ""
	}
	if h.platform.Org == "" || h.platform.Platform == "" {
		h.logger.Warn("resolveRunEntityID: platform identity missing, RunEntityID will be empty",
			slog.String("run_id", runID))
		return ""
	}
	id, err := agentic.TryChainExecutionEntityID(h.platform.Org, h.platform.Platform, runID)
	if err != nil {
		h.logger.Warn("resolveRunEntityID: failed to build chain execution entity ID",
			slog.String("run_id", runID),
			slog.String("org", h.platform.Org),
			slog.String("platform", h.platform.Platform),
			slog.Any("error", err))
		return ""
	}
	return id
}

func (h *MessageHandler) gateForApproval(loopID string, toolResult agentic.ToolResult) (*PublishedMessage, error) {
	// Falls back to the tool name on the result envelope when the
	// LoopManager cache has been cleared (e.g., process restart).
	toolName := h.resolveToolName(toolResult)
	args := h.loopManager.GetToolArguments(toolResult.ExecutionID)

	gate, err := h.loopManager.beginApprovalGate(loopID, toolResult, toolName, args, h.config.ApprovalTimeout())
	if err != nil {
		return nil, err
	}
	return h.approvalPendingMessage(loopID, gate)
}

func (m *LoopManager) HasActiveLoopForTask(taskID string) (string, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	for _, entity := range m.loops {
		if entity.TaskID == taskID && !entity.State.IsTerminal() {
			return entity.ID, true
		}
	}
	return "", false
}

func (h *MessageHandler) synthesizeSkippedQueuedTools(loopID, terminalTool string) {
	queued := h.loopManager.QueuedToolCount(loopID)
	if queued == 0 {
		return
	}
	name := terminalTool
	if name == "" {
		name = "a terminal tool"
	}
	reason := fmt.Sprintf("skipped because %s ended the iteration", name)
	for i := 0; i < queued; i++ {
		next, ok := h.loopManager.DequeueToolCall(loopID)
		if !ok {
			break
		}
		h.logger.Info("queued tool call skipped by a terminal tool; emitting a synthetic result",
			slog.String("loop_id", loopID),
			slog.String("call_id", next.ID),
			slog.String("tool_name", next.Name),
			slog.String("terminal_tool", terminalTool))
		if err := h.synthesizeToolFailure(loopID, next, reason); err != nil {
			h.logger.Warn("failed to store the synthetic result for a skipped queued call",
				slog.String("loop_id", loopID),
				slog.String("call_id", next.ID),
				slog.String("error", err.Error()))
		}
	}
	if remaining := h.loopManager.QueuedToolCount(loopID); remaining > 0 {
		// Reachable: the queue can gain calls while this drains (see the
		// bound's note above). When it fires, those calls are about to be
		// cleared with no results and the next request's tool batch will be
		// repaired away — so this WARN is the only trace of it.
		h.logger.Warn("queued tool calls remain after the skipped-queue drain; they will go unanswered",
			slog.String("loop_id", loopID),
			slog.Int("drained", queued),
			slog.Int("remaining", remaining))
	}
}

func (h *MessageHandler) SetMetrics(m *loopMetrics) {
	h.metrics = m
}

func (m *LoopManager) DeleteLoop(loopID string) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	delete(m.loops, loopID)
	delete(m.pendingTools, loopID)
	delete(m.queuedToolCalls, loopID)
	delete(m.contextManagers, loopID)
	delete(m.cachedTools, loopID)
	delete(m.cachedToolChoice, loopID)
	delete(m.cachedMetadata, loopID)
	delete(m.cachedRequestTimeout, loopID)
	delete(m.cachedResponseFormat, loopID)
	delete(m.outstandingRequests, loopID)

	prefix := loopID + ":"
	for k, owner := range m.requestToLoop {
		if owner == loopID || strings.HasPrefix(k, prefix) {
			delete(m.requestToLoop, k)
			delete(m.requestStartTimes, k)
		}
	}
	for executionID, owner := range m.toolCallToLoop {
		if owner == loopID {
			delete(m.toolCallToLoop, executionID)
			m.deleteToolMetadataLocked(executionID)
		}
	}
	return nil
}

type MessageHandler struct {
	config            Config
	loopManager       *LoopManager
	trajectoryManager *trajectoryManager
	compactor         *Compactor
	// governanceDispatcher implements subject-mode tool-call governance
	// (ADR-039). Set via SetGovernanceDispatcher at component boot. Nil
	// is treated as disabled-mode pass-through (no governance gate).
	// Beta.70 retired the in-process ToolCallFilter wiring that
	// previously co-existed with this dispatcher; subject-mode is now
	// the sole governance path.
	governanceDispatcher GovernanceDispatcher
	modelRegistry        model.RegistryReader
	toolRegistry         component.ToolRegistryReader
	logger               *slog.Logger

	// todoReader fetches the current write_todos list for a loop entity
	// at iteration-build time (ADR-036 Stage 4). Nil disables the
	// per-iteration todo block — fragments and trajectory still work.
	// Set via SetTodoReader at component boot.
	todoReader TodoReader

	// lessonReader lists active lesson-record entities for brief-assembly
	// injection (ADR-080 push-based memory). Nil disables lesson injection
	// entirely (back-compat) — the assembled prompt is unchanged. Set via
	// SetLessonReader at component boot.
	lessonReader LessonReader

	// metrics records brief-assembly observability (lesson matched-vs-included
	// counts). Nil-safe: unset in unit tests, wired at component boot.
	metrics *loopMetrics

	// platform identifies the org/platform pair used to construct loop
	// entity IDs. Empty Org/Platform skips the todo read silently —
	// the loop entity ID is unrecoverable without it.
	platform types.PlatformMeta

	// promptRegistry is the static fragment registry seeded with
	// prompt.DefaultFragments at Component.Start. Nil means no assembler
	// step — buildInitialMessages emits only the existing
	// task.Context.Content + user-prompt pair.
	promptRegistry *prompt.Registry

	// personaFragments loads KV-backed persona overrides on demand.
	// Nil means no overrides (unit tests, or deployments without a
	// PersonaManager). When non-nil, the handler refreshes the merged
	// registry on every task so runtime persona edits (create / update
	// via the CRUD tools) take effect immediately on the next loop
	// without a component restart.
	personaFragments PersonaFragmentSource

	// testApprovedDispatchHook, if non-nil, is called on the approval lane at
	// two named stages of an approve or modify (#1377, design § 3.3):
	// "before_dispatch" after the loop-deadline check and before the decision
	// switch, and "dispatched" after dispatchToolCall has registered the call
	// as pending and before the result reaches the carrier. Tests pause there
	// to force a cancel into the window; no log line exists after
	// AddPendingTool to pause on. Precedent: Component.testPublishHook.
	// Always nil in production.
	testApprovedDispatchHook func(loopID, stage string)
}

func (m *LoopManager) GetTaskPrompt(loopID string) string {
	m.mu.RLock()
	defer m.mu.RUnlock()
	if entity, exists := m.loops[loopID]; exists {
		return entity.TaskPrompt
	}
	return ""
}

func (m *LoopManager) OutstandingRequest(loopID string) string {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.outstandingRequests[loopID]
}

func (m *LoopManager) CacheResponseFormat(loopID string, rf *agentic.ResponseFormat) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.cachedResponseFormat[loopID] = rf
}

func (m *LoopManager) AllToolsComplete(loopID string) bool {
	m.mu.RLock()
	defer m.mu.RUnlock()

	pending := m.pendingTools[loopID]
	return len(pending) == 0
}

func (h *MessageHandler) assembleBasePrompt(ctx context.Context, task TaskMessage) string {
	if h.promptRegistry == nil {
		return ""
	}
	if h.personaFragments != nil {
		fragments, err := h.personaFragments.Fragments(ctx)
		if err != nil {
			h.logger.Warn("failed to refresh persona overrides; falling back to registry state",
				slog.Any("error", err),
				slog.String("task_id", task.TaskID))
		} else if len(fragments) > 0 {
			h.promptRegistry.UpsertAll(fragments)
		}
	}
	actx := &prompt.AssemblyContext{
		Role:          task.Role,
		LoopID:        task.LoopID,
		Depth:         task.Depth,
		MaxDepth:      task.MaxDepth,
		Prompt:        task.Prompt,
		WorkflowSlug:  task.WorkflowSlug,
		WorkflowStep:  task.WorkflowStep,
		Tools:         toolNames(task.Tools),
		Iteration:     0,
		MaxIterations: effectiveLoopMaxIterations(task, h.config.MaxIterations),
		ParentLoopID:  task.ParentLoopID,
		Provider:      h.resolveProvider(task.Model),
	}
	return prompt.Assemble(h.promptRegistry, actx).SystemMessage
}

type PublishedMessage struct {
	Subject string
	Data    []byte
	// MsgID, when non-empty, is stamped as the Nats-Msg-Id header so the
	// server rejects a duplicate of this logical message inside the stream's
	// Duplicates window (owner ruling Q5 on #1330). Every agent.request
	// carries its deterministic RequestID here; an empty MsgID publishes
	// exactly as before.
	MsgID string
}

