func (h *MessageHandler) failLoop(result *HandlerResult, loopID, outcome, reason, errorMsg string) error {
	// Drain any pending tool calls into synth-results before transitioning
	// to terminal state. Modes (c) and (d) of orphan-tool-call recovery —
	// late-arriving results dropped silently; KV-restored loops won't
	// carry orphan tool_calls. No-op when no pending tools exist.
	h.drainPendingToolFailures(loopID, fmt.Sprintf("loop failed: %s", reason))

	if err := h.loopManager.TransitionLoop(loopID, agentic.LoopStateFailed); err != nil {
		return err
	}
	result.State = agentic.LoopStateFailed

	if err := h.loopManager.UpdateCompletion(loopID, outcome, "", errorMsg); err != nil {
		h.logger.Warn("failed to update completion",
			slog.String("loop_id", loopID),
			slog.String("reason", reason),
			slog.String("error", err.Error()))
	}

	if failure, failMsgs, fErr := h.BuildFailureMessages(loopID, reason, errorMsg); fErr == nil {
		result.PublishedMessages = failMsgs
		result.FailureState = failure
	}
	return nil
}

func (h *MessageHandler) HandleTask(ctx context.Context, task TaskMessage) (HandlerResult, error) {
	// Check for cancellation before starting work
	if err := ctx.Err(); err != nil {
		return HandlerResult{}, err
	}

	// Check depth limit before creating loop
	if task.MaxDepth > 0 && task.Depth >= task.MaxDepth {
		return HandlerResult{}, errs.WrapInvalid(
			fmt.Errorf("max agent depth (%d) reached, cannot spawn child agent", task.MaxDepth),
			"agentic-loop",
			"HandleTask",
			"check depth limit",
		)
	}

	// Dedup: if a non-terminal loop already exists for this task, skip.
	// This prevents duplicate LLM work when JetStream redelivers a message
	// (e.g. after a transient heartbeat failure).
	if existingID, exists := h.loopManager.HasActiveLoopForTask(task.TaskID); exists {
		// A conflicting loop token under this TaskID never reaches here: the
		// delivery refuses it in handleTaskMessage, where the token the
		// PRODUCER sent is still distinguishable from one intake minted
		// (preflightDecodedTask reserves a fresh prospective UUID per delivery
		// for a lineage task that named no loop). By this point the two are
		// the same field, so the comparison would read a redelivery as a
		// conflict.
		h.logger.Warn("Duplicate task message — loop already active",
			slog.String("task_id", task.TaskID),
			slog.String("existing_loop_id", existingID))
		return HandlerResult{LoopID: existingID}, nil
	}

	// Use provided loop_id if present, otherwise create new one.
	//
	// A supplied token that already names a registered loop is a CONTINUATION,
	// not a second loop under one name (#1227): CreateLoopWithID refuses it and
	// intake attaches to the live loop instead of minting over its
	// conversation. `continuation` carries that fact through the rest of this
	// function, which otherwise seeds a brand-new loop.
	var loopID string
	var err error
	var continuation, deferred bool
	entity := agentic.LoopEntity{}

	effectiveMaxIterations := effectiveLoopMaxIterations(task, h.config.MaxIterations)

	if task.LoopID != "" {
		loopID, err = h.loopManager.CreateLoopWithID(task.LoopID, task.TaskID, task.Role, task.Model, effectiveMaxIterations)
		switch {
		case err == nil:
		case errors.Is(err, ErrLoopAlreadyExists):
			entity, deferred, err = h.loopManager.attachContinuation(task.LoopID, task.TaskID, task.Prompt)
			if err != nil {
				// A settled loop (ErrLoopTerminal) and a loop with work in
				// flight (ErrLoopBusy) both refuse the continuation outright;
				// nothing has been registered, so there is nothing to roll back
				// and the live loop's own round is untouched.
				return HandlerResult{}, err
			}
			loopID = task.LoopID
			continuation = true
			h.logger.Info("Continuation attached to live loop",
				slog.String("loop_id", loopID),
				slog.String("task_id", task.TaskID),
				slog.String("loop_state", string(entity.State)),
				slog.Bool("deferred", deferred))
		default:
			return HandlerResult{}, err
		}
	} else {
		loopID, err = h.loopManager.CreateLoop(task.TaskID, task.Role, task.Model, effectiveMaxIterations)
		if err != nil {
			return HandlerResult{}, err
		}
	}

	// Configure optional loop metadata (depth, workflow context, user context, etc.)
	h.configureLoopMetadata(loopID, task)

	// Start trajectory. A continuation joins a loop whose aggregate is still
	// accumulating this turn's steps: restarting it would drop them, and the
	// rollback below must not discard work that belongs to the in-flight loop
	// rather than to this task.
	//
	// Residual, known and accepted: when the aggregate is ABSENT on a
	// continuation — reachable only after an earlier HandleTask error on this
	// same loop discarded it — keepTrajectory stays false and the restart drops
	// the steps already accumulated. The consequence is audit loss, not
	// execution failure, which is the correct severity ordering under this
	// capability's rule that audit loss degrades loudly and never fails agent
	// work. What is missing is the "loudly": ADR-068 treats evidence as
	// non-regenerable, so this discard should be counted and logged at the
	// restart rather than passing silently.
	keepTrajectory := false
	if continuation {
		if _, trajErr := h.trajectoryManager.getTrajectory(loopID); trajErr == nil {
			keepTrajectory = true
		}
	}
	if !keepTrajectory {
		if _, err = h.trajectoryManager.startTrajectory(loopID); err != nil {
			return HandlerResult{}, err
		}
	}
	defer func() {
		if !keepTrajectory {
			h.trajectoryManager.discardTrajectory(loopID)
		}
	}()

	// Get loop entity. attachContinuation already returned it for a
	// continuation, but configureLoopMetadata has run since, so re-read either
	// way rather than carrying a stale copy.
	entity, err = h.loopManager.GetLoop(loopID)
	if err != nil {
		return HandlerResult{}, err
	}

	// Assemble the system prompt once. It is stored in RegionSystemPrompt so
	// cm.GetContext() includes it on every continuation iteration (iteration 2+).
	// Without this, the assembled persona is absent from the context manager and
	// omitted from all continuation requests — real LLMs lose their instructions
	// and the mock's marker-based preset doesn't fire after the first tool round.
	//
	// A continuation must NOT re-seed it: the live loop's RegionSystemPrompt
	// already holds the persona it has been running under, and a second copy
	// would be sent alongside the first on every subsequent iteration.
	assembled := ""
	if !continuation {
		assembled = h.assembleSystemPrompt(ctx, task)
	}

	// Add user prompt to context manager and cache for recovery.
	// If GC/repair later empties the context, we re-inject this prompt.
	//
	// On a continuation this is the loop's EXISTING manager — the conversation
	// accumulated so far is still in it, and the new turn is appended after it.
	cm := h.loopManager.GetContextManager(loopID)
	if assembled != "" {
		_ = cm.AddMessage(RegionSystemPrompt, agentic.ChatMessage{
			Role:    "system",
			Content: assembled,
		})
	}

	_ = cm.AddMessage(RegionRecentHistory, agentic.ChatMessage{
		Role:    "user",
		Content: task.Prompt,
	})
	// The loop's prompt is the one that bore it (#1365): written once, at
	// birth, and never by a continuation, whose turn is the record's pending
	// text or its retained request.
	if !continuation {
		h.loopManager.CacheTaskPrompt(loopID, task.Prompt)
	}

	// If embedded context is present, add it directly (skips hydration)
	if task.Context != nil && task.Context.Content != "" {
		_ = cm.AddMessage(RegionGraphEntities, agentic.ChatMessage{
			Role:    "system",
			Content: task.Context.Content,
		})
		h.logger.Debug("Using embedded context",
			slog.String("loop_id", loopID),
			slog.Int("token_count", task.Context.TokenCount),
			slog.Int("entity_count", len(task.Context.Entities)))
	}

	// Build messages for the request with iteration budget. Pass the
	// already-assembled system prompt so we avoid assembling a second time.
	// prependIterationContext also injects the working-list block from
	// write_todos when the loop has any todos (ADR-036 Stage 4).
	//
	// A continuation takes the loop's whole accumulated context instead — the
	// same source every other continuation iteration uses (buildRetryRequest,
	// handleToolsComplete). Reusing the context manager and then sending the
	// model only the new turn would preserve the conversation nowhere it can be
	// observed. The iteration ordinal is the loop's own, not 1, so the budget
	// message the model reads is the budget it is actually spending.
	iteration := 1
	if continuation && entity.Iterations > iteration {
		iteration = entity.Iterations
	}
	var messages []agentic.ChatMessage
	if continuation {
		messages = cm.GetContext()
	} else {
		messages = h.buildInitialMessagesWithPrompt(task, assembled)
	}
	messages = h.prependIterationContext(ctx, loopID, iteration, entity.MaxIterations, messages)

	// Per-task tools: if the spawner set task.Tools (including an explicit
	// empty slice from e.g. `"default_tools": []`), respect it. Only fall
	// back to global discovery when the field is truly unset (nil). This is
	// the gate that lets a flow say "this role gets no tools at all" —
	// critical for role scoping done at the product layer.
	var tools []agentic.ToolDefinition
	if task.Tools != nil {
		tools = task.Tools
	} else {
		tools = h.discoverTools()
	}
	h.loopManager.CacheTools(loopID, tools)

	// Cache tool choice strategy for all iterations in this loop
	if task.ToolChoice != nil {
		h.loopManager.CacheToolChoice(loopID, task.ToolChoice)
	}

	// Cache domain metadata for propagation to tool calls
	if len(task.Metadata) > 0 {
		h.loopManager.CacheMetadata(loopID, task.Metadata)
	}

	// Cache per-task request timeout so continuation iterations reuse it.
	if task.Timeout != "" {
		h.loopManager.CacheRequestTimeout(loopID, task.Timeout)
	}

	// Cache per-task response_format (ADR-034) so continuation iterations
	// reuse the structured-output constraint. Nil leaves tool-calling
	// behaviour unchanged across the loop.
	if task.ResponseFormat != nil {
		h.loopManager.CacheResponseFormat(loopID, task.ResponseFormat)
	}

	// The deferral itself. Everything above has run — the turn is in the loop's
	// context, the caches the next request reads carry this task's tools, tool
	// choice, metadata, timeout and response format — and the one thing that
	// does NOT happen is the publish. Minting a request now would reuse the
	// outstanding request's `<loopID>:req:<iteration>:<retry>` name, and the
	// duplicate window would drop it: same name, different bytes. The
	// outstanding response carries this turn into iteration N+1 instead.
	if deferred {
		keepTrajectory = true
		return h.deferredContinuationResult(loopID, task.TaskID, task.Prompt, entity), nil
	}

	result, err := h.buildTaskRequest(loopID, task, entity, messages, tools)
	if err != nil {
		// A failure here, at startTrajectory or at GetLoop above leaves the
		// loop registered (a birth) or its TaskID rebound (a continuation), and
		// no record touched; the task lane retries it by class, and the retry
		// meets HasActiveLoopForTask and is acknowledged as a duplicate with the
		// turn nowhere durable. No production path fails at any of the three:
		// startTrajectory always returns nil, GetLoop fails only on a release
		// race, and buildTaskRequest's marshal and ResolveSubject never do — so
		// no release code guards them (#1345, design § 6.12, § 7.3).
		return HandlerResult{}, err
	}
	keepTrajectory = true
	return result, nil
}

func (m *LoopManager) CacheTaskPrompt(loopID, prompt string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if entity, exists := m.loops[loopID]; exists {
		entity.TaskPrompt = prompt
	}
}

func (h *MessageHandler) approvalPendingMessage(loopID string, gate agentic.PendingApprovalState) (*PublishedMessage, error) {
	pending := &agentic.ApprovalPendingEvent{
		LoopID: loopID,
		CallID: gate.CallID,
		// The identity the approval authorises, carried to whoever answers so
		// the answer can be matched on it rather than on a provider CallID the
		// provider may reuse next turn.
		ExecutionID: gate.ExecutionID,
		RequestID:   gate.RequestID,
		ToolName:    gate.ToolName,
		Arguments:   gate.Arguments,
		Reason:      gate.Reason,
		RequestedAt: gate.RequestedAt,
		Timeout:     gate.Timeout,
		TraceID:     gate.TraceID,
	}
	envelope := message.NewBaseMessage(pending.Schema(), pending, "agentic-loop")
	data, err := json.Marshal(envelope)
	if err != nil {
		return nil, fmt.Errorf("marshal approval pending event: %w", err)
	}
	subject, err := component.ResolveSubject(h.config.Ports.Outputs, "agent.approval_pending", loopID)
	if err != nil {
		return nil, err
	}
	return &PublishedMessage{
		Subject: subject,
		Data:    data,
	}, nil
}

func isValidOutcome(outcome string) bool {
	switch outcome {
	case agentic.OutcomeSuccess, agentic.OutcomeFailed, agentic.OutcomeCancelled, agentic.OutcomeTruncated:
		return true
	default:
		return false
	}
}

func (m *LoopManager) RemovePendingTool(loopID, callID string) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.pendingTools[loopID] != nil {
		delete(m.pendingTools[loopID], callID)
	}

	return nil
}

func (m *LoopManager) GetToolOrdinal(executionID string) uint32 {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.executionIDToOrdinal[executionID]
}

func (h *MessageHandler) BuildFailureEvent(loopID, reason, errorMsg string) (*agentic.LoopFailedEvent, error) {
	return h.buildFailureEvent(loopID, reason, errorMsg)
}

func (m *LoopManager) TrackToolOrdinal(executionID string, ordinal uint32) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.executionIDToOrdinal[executionID] = ordinal
}

func (h *MessageHandler) computeToolDuration(executionID string) int64 {
	if start := h.loopManager.GetToolStart(executionID); !start.IsZero() {
		return time.Since(start).Milliseconds()
	}
	h.logger.Warn("missing tool start time for duration computation",
		slog.String("execution_id", executionID))
	return 0
}

func (h *MessageHandler) prependIterationContext(ctx context.Context, loopID string, iteration, maxIterations int, messages []agentic.ChatMessage) []agentic.ChatMessage {
	prefix := []agentic.ChatMessage{BuildIterationBudgetMessage(iteration, maxIterations)}
	if todoMsg := h.maybeBuildTodoMessage(ctx, loopID); todoMsg.Content != "" {
		prefix = append(prefix, todoMsg)
	}
	return append(prefix, messages...)
}

func (h *MessageHandler) assembleLessonBlock(ctx context.Context, task TaskMessage) string {
	if h.lessonReader == nil || h.platform.Org == "" || h.platform.Platform == "" {
		return ""
	}
	scope := deriveLoopScope(task)
	if len(scope.Tags) == 0 && len(scope.EntityIDs) == 0 {
		return "" // empty scope matches nothing — skip the read entirely
	}

	recordPrefix := agentic.AgentLessonRecordPrefix(h.platform.Org, h.platform.Platform)
	candidates, err := h.lessonReader.ReadLessons(ctx, recordPrefix)
	if err != nil {
		h.logger.Warn("lesson read failed; brief carries no lesson block this dispatch",
			slog.Any("error", err),
			slog.String("task_id", task.TaskID))
		return ""
	}

	res := lessonmatch.Match(candidates, scope, lessonmatch.Opts{})
	if h.metrics != nil {
		h.metrics.recordLessonInjection(res.MatchedCount, res.IncludedCount)
	}
	return renderLessonBlock(res)
}

func (m *LoopManager) CreateLoop(taskID, role, model string, maxIterations ...int) (string, error) {
	loopID := m.GenerateLoopID()
	return m.CreateLoopWithID(loopID, taskID, role, model, maxIterations...)
}

func (m *LoopManager) GetLoopForRequest(requestID string) (string, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	loopID, exists := m.requestToLoop[requestID]
	return loopID, exists
}

func (h *MessageHandler) HandleModelResponse(ctx context.Context, loopID string, response agentic.AgentResponse) (HandlerResult, error) {
	// Check for cancellation before starting work. Nothing has been touched
	// yet, so the delivery may be retried — the same marker the tool lane
	// carries (errCancelledBeforeMutation). Without it the response lane
	// failed the loop on a cancelled delivery context, and under the
	// create-once terminal marker that failure is permanent (#1362 review,
	// owner ruling 3 in issuecomment-5808903072).
	if err := ctx.Err(); err != nil {
		return HandlerResult{}, fmt.Errorf("%w: %w", errCancelledBeforeMutation, err)
	}
	entity, err := h.loopManager.GetLoop(loopID)
	if err != nil {
		return HandlerResult{}, err
	}
	// Identity decides whether this response may advance the loop, BEFORE any
	// completion logic reads it. Only the loop's CURRENT request can: a
	// response naming an earlier one is superseded, and acting on it acts on a
	// world two moves old.
	//
	// Current, not outstanding. The outstanding mark is cleared the moment a
	// response settles, and a tool-call response settles its request while the
	// loop stays on that iteration waiting for executors or an approval — so
	// "the loop is waiting on nothing" is the loop's ordinary mid-iteration
	// state, not evidence that a response belongs to it. An earlier request's
	// redelivered completion arriving in that window would pass an emptiness
	// test and settle the loop with the PREVIOUS task's answer while the
	// current request — the one carrying the user's newer turn — is still
	// being worked. Reproduced sequentially by the owner's round-2 review; no
	// concurrency and no restart needed.
	//
	// The terminal guard below cannot stand in for this. A completion response
	// that carried a deferred continuation leaves the loop NON-terminal at the
	// next iteration, so its JetStream redelivery — AckWait and MaxDeliver are
	// declared at config.go:169-171 and the agent.response lane resolves them
	// with its BackOff at component.go:956-992, and it has no dedup of its own —
	// meets no terminal state, finds no turn left to carry, and would complete the loop
	// while the request carrying the user's turn is still in flight. That
	// request's own answer would then be dropped by the terminal guard, which is
	// exactly the lost turn the deferral exists to prevent.
	//
	// A redelivery of the CURRENT request passes THIS check: same identity,
	// same request, and refusing it here would drop the answer the loop is
	// owed. Whether it is the answer the loop is still owed or a replay of one
	// already used is the outstanding mark's question, below (Q12).
	//
	// The identity compared against is the DURABLE one — the request the
	// loop's record names (#1330, I1). It used to be LoopManager.CurrentRequest,
	// a process-local map that is empty after a replacement, so every response
	// reaching a rebuilt process passed this guard whatever it named (L2's
	// declared residual). The record's name survives the process, so a
	// replacement classifies with the same authority the original had.
	order := orderAgainstPublished(loopID, entity.PublishedRequestID, response.RequestID)
	switch order {
	case requestOrderApplied:
		h.logger.Warn("ignoring superseded model response — the loop has moved on to a different request",
			slog.String("loop_id", loopID),
			slog.String("response_request_id", response.RequestID),
			slog.String("published_request_id", entity.PublishedRequestID),
			slog.String("outstanding_request_id", h.loopManager.OutstandingRequest(loopID)),
			slog.String("state", entity.State.String()))
		if h.metrics != nil {
			h.metrics.recordModelResponseDropped("superseded_request")
		}
		return HandlerResult{}, fmt.Errorf("%w: loop %s response names request %q, its record names %q",
			errResponseSuperseded, loopID, response.RequestID, entity.PublishedRequestID)
	case requestOrderForeign:
		h.logger.Warn("refusing a model response that names a request of no loop",
			slog.String("loop_id", loopID),
			slog.String("response_request_id", response.RequestID),
			slog.String("published_request_id", entity.PublishedRequestID),
			slog.String("state", entity.State.String()))
		return HandlerResult{}, fmt.Errorf("%w: loop %s response names request %q, its record names %q",
			errResponseForeign, loopID, response.RequestID, entity.PublishedRequestID)
	case requestOrderAhead:
		// The answer arrived before the record that names its question. It is
		// not superseded and must not be dropped: the delivery is retried
		// until the record catches up, which is the only reading under which
		// the record stays the authority (#1330, design § 5.2).
		return HandlerResult{
				LoopID:            loopID,
				State:             entity.State,
				PublishedMessages: []PublishedMessage{},
				TrajectorySteps:   []agentic.TrajectoryStep{},
				ContextEvents:     []agentic.ContextEvent{},
			}, fmt.Errorf("%w: loop %s response names request %q, its record names %q",
				errRequestNotYetObservable, loopID, response.RequestID, entity.PublishedRequestID)
	}
	// The fourth case, which ORDERING cannot reach: a second delivery of the
	// answer this loop is currently on. Both deliveries name the request the
	// record names, so the record is the same authority either way; what
	// separates them is the outstanding mark, which SettleRequest clears below
	// the moment an answer is used. A response naming the current request
	// while the loop is waiting on NO request is therefore one this process
	// already applied, and applying it again appends the assistant turn a
	// second time and re-dispatches its calls — the duplicate turn then rides
	// the next request the model is asked to answer (#1330, owner ruling Q12,
	// 2026-09-23).
	//
	// Scoped to requestOrderCurrent deliberately. requestOrderUnnamed reaches
	// here too — a record written before this field existed, or a producer
	// that correlates neither side — and it has no mark to compare, so it
	// keeps the pre-#1330 answer rather than being dropped on an absence.
	//
	// A loop REBUILT for this very response is not a replay: restoreLoopFromRequest
	// marks the retained request outstanding from the only evidence it has
	// (its publication), so the cold arm's first delivery passes this gate.
	if order == requestOrderCurrent && h.loopManager.OutstandingRequest(loopID) != response.RequestID {
		h.logger.Warn("ignoring a model response this loop already applied — it is waiting on no request",
			slog.String("loop_id", loopID),
			slog.String("response_request_id", response.RequestID),
			slog.String("published_request_id", entity.PublishedRequestID),
			slog.String("state", entity.State.String()))
		if h.metrics != nil {
			h.metrics.recordModelResponseDropped("already_applied")
		}
		return HandlerResult{}, fmt.Errorf("%w: loop %s response names request %q, which the loop is "+
			"no longer waiting on", errResponseAlreadyApplied, loopID, response.RequestID)
	}

	// Reject responses for loops already in terminal state (defense-in-depth:
	// catches stale agent.request messages published before a parallel StopLoop
	// transition was visible). It runs BEFORE anything is touched — the
	// outstanding mark, the timeout arm — so the result is truly effect-free:
	// the timeout arm would otherwise rewrite Outcome and Error on a terminal
	// whose commit may be in flight on another lane (#1362 re-review M2).
	if entity.State.IsTerminal() {
		h.logger.Warn("ignoring model response for terminal loop",
			slog.String("loop_id", loopID),
			slog.String("state", entity.State.String()))
		return terminalGuardResult(loopID, entity.State), nil
	}

	// This request is answered, whatever the outcome below. Clearing the
	// outstanding mark here rather than in the success arms means an early
	// return (timeout, terminal loop, budget exhausted) does not leave the loop
	// looking like it is still waiting on a model.
	//
	// The early clear is for the outstanding mark. A deferred turn's carrier is
	// settled with it on every status but one: a length_truncated answer did
	// not answer the turn, so the deferral survives into the compaction retry
	// and recoverEmptyContext can still re-inject it (#1365, F3).
	if response.Status == agentic.StatusLengthTruncated {
		h.loopManager.settleTruncatedRequest(loopID, response.RequestID)
	} else {
		h.loopManager.SettleRequest(loopID, response.RequestID)
	}
	result := HandlerResult{
		LoopID:            loopID,
		State:             entity.State,
		PublishedMessages: []PublishedMessage{},
		TrajectorySteps:   []agentic.TrajectoryStep{},
		ContextEvents:     []agentic.ContextEvent{},
	}
	appendTrajectoryObservation(&result, trajectoryObservation{
		LoopID:            loopID,
		Kind:              agentic.TrajectoryKindModelCompleted,
		SourceKind:        agentic.TrajectorySourceRequest,
		SourceCorrelation: response.RequestID,
		CausalIteration:   positiveUint32(entity.Iterations),
		CausalPhase:       agentic.TrajectoryPhaseModelResult,
		ElapsedMS:         h.computeRequestDuration(response.RequestID),
		Status:            modelResponseStatus(response),
		TokensIn:          positiveUint64(response.TokenUsage.PromptTokens),
		TokensOut:         positiveUint64(response.TokenUsage.CompletionTokens),
		ToolCount:         uint32(len(response.Message.ToolCalls)),
		ModelPreview:      entity.Model,
		ProviderPreview:   h.resolveProvider(entity.Model),
		CapabilityPreview: entity.Role,
		ErrorCategory:     modelResponseErrorCategory(response),
		Evidence:          response,
	})

	// Check for timeout before processing
	if h.loopManager.IsTimedOut(loopID) {
		return h.failTimedOutLoop(loopID, result, "HandleModelResponse")
	}

	// Check if max iterations reached
	if entity.Iterations >= entity.MaxIterations {
		return result, errs.WrapFatal(
			fmt.Errorf("%w: loop %s at %d/%d iterations", ErrMaxIterationsReached, loopID, entity.Iterations, entity.MaxIterations),
			"agentic-loop",
			"HandleModelResponse",
			"check max iterations",
		)
	}

	// Record trajectory step
	step := agentic.TrajectoryStep{
		Timestamp:  time.Now(),
		StepType:   "model_call",
		RequestID:  response.RequestID,
		Response:   response.Message.Content,
		TokensIn:   response.TokenUsage.PromptTokens,
		TokensOut:  response.TokenUsage.CompletionTokens,
		Duration:   h.computeRequestDuration(response.RequestID),
		Model:      entity.Model,
		Provider:   h.resolveProvider(entity.Model),
		Capability: entity.Role,
		RetryCount: response.RetryCount,
	}
	result.TrajectorySteps = append(result.TrajectorySteps, step)

	// Eagerly add step to trajectory manager so token totals are available
	// when handleCompleteResponse queries the trajectory for cost tracking.
	if _, addErr := h.trajectoryManager.addStep(loopID, step); addErr != nil {
		h.logger.Warn("failed to add trajectory step",
			slog.String("loop_id", loopID),
			slog.String("error", addErr.Error()))
	}

	// Add assistant response to context manager if enabled.
	// Must store tool_call messages even when content is empty — they are
	// required in the conversation history for the next model request.
	//
	// Truncated responses are EXCLUDED from this path: a partial
	// assistant turn must not pollute the context (the next request
	// would see the orphan and either continue from a half-finished
	// draft or, with tool_calls present in the partial turn, break
	// tool_use/tool_result pair integrity). Compaction is also
	// deliberately skipped here for the truncated case —
	// handleLengthTruncation owns the compact-and-retry decision below
	// and reads pre-compaction utilization to make it; running
	// maybeCompact here first would post-compact the context before
	// the decision and make the diagnostic / retry-vs-fail branch
	// see stale numbers.
	cm := h.loopManager.GetContextManager(loopID)
	hasContent := response.Message.Content != "" || response.Message.ReasoningContent != "" || len(response.Message.ToolCalls) > 0
	if hasContent && response.Status != agentic.StatusLengthTruncated {
		_ = cm.AddMessage(RegionRecentHistory, response.Message)
		h.maybeCompact(ctx, cm, loopID, entity.Iterations, &result)
	}

	switch response.Status {
	case agentic.StatusToolCall:
		// Forward progress needs no explicit reset since #1330: the next
		// request this loop mints names a NEW iteration, and a new iteration
		// always starts at retry ordinal 0, so the self-heal budget renews
		// itself in the name rather than in a counter somebody has to clear.

		if err := h.handleToolCallResponse(ctx, &result, loopID, response.RequestID, response.Message.ToolCalls); err != nil {
			return result, err
		}

		// Edge case: if filtering (empty-name rejection or governance
		// reject) removed ALL calls, no tool.execute messages were
		// published so no tool results will arrive. Trigger tools-
		// complete immediately.
		if h.loopManager.AllToolsComplete(loopID) {
			completionResult, err := h.handleToolsComplete(ctx, loopID, entity, cm, &result)
			if err != nil {
				return completionResult, err
			}
			return completionResult, nil
		}

	case agentic.StatusComplete:
		// gh#158: fall back to ReasoningContent when Content is empty so
		// the LLM's terminal text always lands on Result + downstream
		// read_loop_result, even when the provider adapter routed it to
		// the non-canonical field.
		completionText := resolveCompletionText(response.Message)

		// A continuation was admitted while this request was outstanding and
		// published nothing, because minting a request then would have reused
		// this request's name. Completing now would settle the loop with that
		// turn unanswered and no later request to carry it — the case the
		// "deferred, not dropped" claim was false for. The loop advances
		// instead, and only a loop with nothing deferred completes here.
		if h.loopManager.HasPendingContinuation(loopID) {
			carried, err := h.carryDeferredContinuation(ctx, loopID, entity, cm, &result)
			if err != nil {
				return result, err
			}
			if carried {
				return result, nil
			}
		}

		// Model-text completion: no terminal tool, so no typed decision.
		if err := h.handleCompleteResponse(&result, loopID, entity, completionText, nil); err != nil {
			return result, err
		}

	case agentic.StatusLengthTruncated:
		if err := h.handleLengthTruncation(ctx, loopID, entity, cm, response, &result); err != nil {
			return result, err
		}

	case agentic.StatusError:
		if err := h.failLoop(&result, loopID, agentic.OutcomeFailed, "model_error", response.Error); err != nil {
			return result, err
		}
	}

	return result, nil
}

func WithLoopManagerLogger(logger *slog.Logger) LoopManagerOption {
	return func(lm *LoopManager) {
		lm.logger = logger
	}
}

func (h *MessageHandler) SetPromptRegistry(r *prompt.Registry) {
	h.promptRegistry = r
}

func (m *LoopManager) settleTerminal(loopID string, adopted *terminalOutcome) {
	m.mu.Lock()
	defer m.mu.Unlock()

	entity, exists := m.loops[loopID]
	if !exists {
		return
	}
	entity.PendingApproval = nil
	entity.StateBeforeApproval = ""
	if adopted == nil {
		return
	}
	switch {
	case adopted.completed != nil:
		reseatTerminalKind(entity, agentic.LoopStateComplete, agentic.OutcomeSuccess)
		entity.Result = adopted.completed.Result
		entity.Error = ""
		entity.CancelledBy, entity.CancelledAt = "", time.Time{}
		entity.CompletedAt = adopted.completed.CompletedAt
	case adopted.failed != nil:
		reseatTerminalKind(entity, agentic.LoopStateFailed, agentic.OutcomeFailed)
		entity.Result = ""
		entity.Error = adopted.failed.Error
		entity.CancelledBy, entity.CancelledAt = "", time.Time{}
		entity.CompletedAt = adopted.failed.FailedAt
	case adopted.cancelled != nil:
		// As the cold cancel adoption writes it (writeRecordCancelled).
		reseatTerminalKind(entity, agentic.LoopStateCancelled, agentic.OutcomeCancelled)
		entity.Result = ""
		entity.Error = cancelledByUserError
		entity.CancelledBy = adopted.cancelled.CancelledBy
		entity.CancelledAt = adopted.cancelled.CancelledAt
		entity.CompletedAt = adopted.cancelled.CancelledAt
	}
}

func (m *LoopManager) SetUserContext(loopID, channelType, channelID, userID string) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	entity, exists := m.loops[loopID]
	if !exists {
		return errs.Wrap(fmt.Errorf("loop %s not found", loopID), "LoopManager", "operation", "find loop")
	}

	entity.ChannelType = channelType
	entity.ChannelID = channelID
	entity.UserID = userID
	return nil
}

func (h *MessageHandler) SetTodoReader(r TodoReader) {
	h.todoReader = r
}

func (m *LoopManager) SetTimeout(loopID string, timeout time.Duration) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	entity, exists := m.loops[loopID]
	if !exists {
		return errs.Wrap(fmt.Errorf("loop %s not found", loopID), "LoopManager", "operation", "find loop")
	}

	now := time.Now()
	entity.StartedAt = now
	entity.TimeoutAt = now.Add(timeout)
	return nil
}

func hasDecideToolCall(steps []agentic.TrajectoryStep) bool {
	for _, s := range steps {
		if s.StepType == "tool_call" && s.ToolName == agentic.DecideToolName {
			return true
		}
	}
	return false
}

func (h *MessageHandler) checkApprovalGate(loopID string, entity *agentic.LoopEntity, toolResult agentic.ToolResult, result *HandlerResult) bool {
	// If the loop is already awaiting approval, store the result and
	// the trajectory step (done by caller) but stop here. Sibling
	// tool results from the same batch can land after the first
	// approval_required hit gated the loop — they must not advance the
	// loop or trigger the next model request. The pending approval
	// handler drains PendingToolResults when the loop resumes.
	//
	// The gated result ITSELF arriving again is a redelivery — its
	// acknowledgement was lost — and the ApprovalPendingEvent it produced may
	// never have been seen. It is re-echoed from the gate the loop holds
	// (#1362 task 1.3, design § 5.4, D28); the carrier writes the gate before
	// it publishes, as for the first echo. Only an approval_required result
	// re-echoes — the same test the cold arm applies — and it is matched by the
	// one identity rule an answer is matched by, so a sibling never echoes a
	// gate it is not.
	if entity.State == agentic.LoopStateAwaitingApproval {
		if agentic.IsApprovalRequired(toolResult.Error) &&
			approvalAnswersGate(entity.PendingApproval, toolResult.CallID, toolResult.ExecutionID) {
			echo, err := h.approvalPendingMessage(loopID, *entity.PendingApproval)
			if err != nil {
				h.logger.Warn("failed to re-echo the pending approval for a redelivered gated result",
					slog.String("loop_id", loopID),
					slog.String("execution_id", toolResult.ExecutionID),
					slog.String("error", err.Error()))
			} else {
				result.PublishedMessages = append(result.PublishedMessages, *echo)
			}
		}
		// Residual: a result that is NOT approval_required yet carries the
		// gated execution is absorbed as a sibling and replaces the gate's
		// placeholder; no production path sends one, and it is stored before
		// this branch runs, while a handler error here would quarantine.
		return true
	}
	// Approval-gated rejection: the agentic-tools approval filter
	// returned an "approval_required: ..." error. Pause the loop,
	// snapshot the call, and emit ApprovalPendingEvent so a
	// product-layer UI can surface the request.
	if !agentic.IsApprovalRequired(toolResult.Error) {
		return false
	}
	pubMsg, err := h.gateForApproval(loopID, toolResult)
	var refused *gateRefusedError
	if errors.As(err, &refused) {
		// The loop settled after the terminal guard let this result in. No
		// gate was written, so claiming awaiting_approval would have the
		// carrier render the live — terminal — entity into the record, a
		// terminal committed outside its owner. The record decides instead.
		h.logger.Warn("approval gate refused: the loop settled before it could gate",
			slog.String("loop_id", loopID),
			slog.String("execution_id", toolResult.ExecutionID),
			slog.String("error", err.Error()))
		*result = terminalGuardResult(loopID, refused.state)
		return true
	}
	if err != nil {
		h.logger.Warn("failed to gate loop for approval",
			slog.String("loop_id", loopID),
			slog.String("call_id", toolResult.CallID),
			slog.String("error", err.Error()))
	} else if pubMsg != nil {
		result.PublishedMessages = append(result.PublishedMessages, *pubMsg)
	}
	result.State = agentic.LoopStateAwaitingApproval
	return true
}

func (m *LoopManager) deferredContinuationPrompt(loopID string) string {
	m.mu.RLock()
	defer m.mu.RUnlock()
	entity, exists := m.loops[loopID]
	if !exists || !entity.PendingContinuation {
		return ""
	}
	return entity.PendingContinuationPrompt
}

func (h *MessageHandler) GetLoop(loopID string) (agentic.LoopEntity, error) {
	return h.loopManager.GetLoop(loopID)
}

func (m *LoopManager) TrackToolCall(executionID, loopID string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.toolCallToLoop[executionID] = loopID
}

func (m *LoopManager) TrackRequestStart(requestID string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.requestStartTimes[requestID] = time.Now()
}

func (h *MessageHandler) SetPersonaFragments(src PersonaFragmentSource) {
	h.personaFragments = src
}

func (m *LoopManager) UpdateLoop(entity agentic.LoopEntity) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	if _, exists := m.loops[entity.ID]; !exists {
		return errs.Wrap(fmt.Errorf("loop %s not found", entity.ID), "LoopManager", "UpdateLoop", "find loop")
	}

	m.loops[entity.ID] = &entity
	return nil
}

func (m *LoopManager) GenerateRequestID(loopID string) string {
	m.mu.RLock()
	defer m.mu.RUnlock()

	next := looprequest.ID{LoopID: loopID, Iteration: 1}
	entity, exists := m.loops[loopID]
	if !exists {
		return next.String()
	}
	next.Iteration = entity.Iterations + 1
	published, err := looprequest.Parse(entity.PublishedRequestID)
	if err == nil && published.LoopID == loopID && published.Iteration == next.Iteration {
		// Minting a second name for an iteration the record already names is
		// the truncation retry, and only that.
		next = looprequest.Next(published, true)
	}
	return next.String()
}

func (m *LoopManager) beginApprovalGate(
	loopID string, toolResult agentic.ToolResult, toolName string, args map[string]any, timeout time.Duration,
) (agentic.PendingApprovalState, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	entity, exists := m.loops[loopID]
	if !exists {
		return agentic.PendingApprovalState{}, &gateRefusedError{loopID: loopID}
	}
	if entity.State.IsTerminal() {
		return agentic.PendingApprovalState{}, &gateRefusedError{loopID: loopID, state: entity.State}
	}
	if err := entity.BeginAwaitingApproval(
		toolResult.CallID, toolName, args, toolResult.Error, timeout, toolResult.TraceID); err != nil {
		return agentic.PendingApprovalState{}, fmt.Errorf("begin awaiting approval: %w", err)
	}
	entity.PendingApproval.RequestID = toolResult.RequestID
	entity.PendingApproval.ExecutionID = toolResult.ExecutionID
	entity.PendingApproval.CallOrdinal = toolResult.CallOrdinal
	// Clear sibling tool calls queued behind this one. Once the human
	// responds, the LLM will get a fresh round-trip with the approve/reject
	// result and can decide whether to re-issue the other calls.
	delete(m.queuedToolCalls, loopID)
	return *entity.PendingApproval, nil
}

func (m *LoopManager) ExtractLoopIDFromRequest(requestID string) string {
	parts := strings.Split(requestID, ":req:")
	if len(parts) >= 1 && parts[0] != "" {
		return parts[0]
	}
	return ""
}

func (m *LoopManager) TrackToolStart(executionID string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.executionStartTimes[executionID] = time.Now()
}

func (m *LoopManager) restoreToolBatch(
	loopID string,
	response agentic.AgentResponse,
	applied map[string]agentic.ToolResult,
	inFlight string,
) error {
	calls := make([]agentic.ToolCall, len(response.Message.ToolCalls))
	copy(calls, response.Message.ToolCalls)
	if err := stampToolExecutionCorrelation(response.RequestID, calls); err != nil {
		return errs.WrapInvalid(err, "LoopManager", "restoreToolBatch",
			"re-derive the retained batch's execution identities")
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	cm, held := m.contextManagers[loopID]
	if !held {
		return errs.Wrap(fmt.Errorf("loop %s: %w", loopID, ErrLoopNotFound),
			"LoopManager", "restoreToolBatch", "find the rebuilt conversation")
	}
	// The assistant turn the batch belongs to. It is in the retained RESPONSE,
	// never in the retained request, and without it every tool message the
	// batch produces is an orphan that RepairToolPairs removes — taking the
	// model's own tool calls out of the next request with it.
	if err := cm.AddMessage(RegionRecentHistory, response.Message); err != nil {
		return errs.WrapTransient(err, "LoopManager", "restoreToolBatch",
			"replay the assistant turn the batch belongs to")
	}

	// An approval gate's approval_required result is a placeholder, not an
	// answer: the gated call's real result is still owed, so its execution is
	// routed like any unanswered one. And the gate cleared the calls queued
	// behind it when it fired (gateForApproval) — the record carries that only
	// as the placeholder — so a batch that holds one rebuilds with an empty
	// queue, as the process that gated it held (#1362 checkpoint 2).
	gated := false
	var queued []agentic.ToolCall
	for _, call := range calls {
		m.executionIDToName[call.ExecutionID] = call.Name
		m.executionIDToOrdinal[call.ExecutionID] = call.CallOrdinal
		stored, done := applied[call.ExecutionID]
		if done && agentic.IsApprovalRequired(stored.Error) {
			// A gated call's arguments are NOT seated. An approval may have
			// dispatched a human's modified set, and the retained response
			// holds only the proposal: omit, do not falsify (owner ruling,
			// #1362 issuecomment-5827720719). An approval applied on this
			// rebuild re-seats the real set at dispatch (dispatchToolCall →
			// TrackToolArguments); a result recovered cold records no
			// dispatch arguments.
			gated = true
			m.toolCallToLoop[call.ExecutionID] = loopID
			continue
		}
		m.executionIDToArguments[call.ExecutionID] = call.Arguments
		if done {
			// Already answered. Its route stays unseated on purpose: a drained
			// execution is unroutable on the ordinary path too, which is what
			// keeps a late duplicate out of the next turn's applied set.
			continue
		}
		m.toolCallToLoop[call.ExecutionID] = loopID
		if call.ExecutionID == inFlight {
			continue
		}
		queued = append(queued, call)
	}
	if gated {
		queued = nil
	}
	m.queuedToolCalls[loopID] = queued

	// pendingTools stays empty on purpose. Dispatch is serial: at most one
	// call is in flight, and the QUEUE is what says how much of the batch is
	// left. HandleToolResult dispatches from that queue before it ever asks
	// AllToolsComplete, so a rebuilt loop with a non-empty queue cannot
	// advance early, and one with an empty queue has nothing left but the
	// result it is applying — which is the same answer pendingTools would
	// give. Seating it would be a second bookkeeping of one fact.

	// The response for this request is in hand, so the loop is not waiting on
	// a model. SettleRequest's half, applied to the mark restoreLoopFromRequest
	// set from the only evidence it had.
	if outstanding, ok := m.outstandingRequests[loopID]; ok && outstanding == response.RequestID {
		delete(m.outstandingRequests, loopID)
	}
	return nil
}

type trajectoryDeferredContinuationEvidence struct {
	TaskID              string `json:"task_id"`
	OutstandingRequest  string `json:"outstanding_request_id"`
	LoopStateAtDeferral string `json:"loop_state"`
}

func (h *MessageHandler) buildInitialMessagesWithPrompt(task TaskMessage, assembled string) []agentic.ChatMessage {
	var messages []agentic.ChatMessage

	if assembled != "" {
		messages = append(messages, agentic.ChatMessage{
			Role:    "system",
			Content: assembled,
		})
	}

	// If embedded context exists, include it as system message first
	if task.Context != nil && task.Context.Content != "" {
		messages = append(messages, agentic.ChatMessage{
			Role:    "system",
			Content: fmt.Sprintf("[Context]\n%s", task.Context.Content),
		})
	}

	// Add user prompt
	messages = append(messages, agentic.ChatMessage{
		Role:    "user",
		Content: task.Prompt,
	})

	return messages
}

func (m *LoopManager) GetAndClearToolResults(loopID string) []agentic.ToolResult {
	m.mu.Lock()
	defer m.mu.Unlock()

	entity, exists := m.loops[loopID]
	if !exists {
		return nil
	}

	results := make([]agentic.ToolResult, 0, len(entity.PendingToolResults))
	for executionID, r := range entity.PendingToolResults {
		results = append(results, r)
		delete(m.toolCallToLoop, executionID)
	}
	entity.PendingToolResults = nil
	return results
}
